//! Raw FFI bindings to the Babylon Lite native API.
//!
//! Everything here is generated by `generate-bindings.ps1` from
//! `Core/LiteLayer/Include/babylon_lite.h` and
//! `Core/LiteShaderCompiler/Include/babylon_lite_shader_compiler.h`; the header
//! comments are the contract. Use the `babylon-lite` crate for a safe API.
//!
//! C enums are newtypes (for example `bl_Status::BL_OK`) so that any value the
//! native side returns is representable.

#![no_std]
#![allow(non_camel_case_types, non_snake_case, non_upper_case_globals)]
#![allow(clippy::all)]

include!("bindings.rs");
